function UtilityDemo({ state }: { state: FixtureState }) {
    const [checked,setChecked] = useState(false); const nextId = useRef(0); const [feedback,setFeedback] = useState("");
    const [files,setFiles] = useState<PrismAttachment[]>(() => state === "loading" ? [{id:"demo-upload",name:"가상_자료.pdf",sizeLabel:"1KB",status:"uploading"}]
        : state === "error" ? [{id:"demo-error",name:"가상_자료.pdf",status:"error",error:"가상 업로드 오류입니다."}]
        : state === "disabled" ? [{id:"demo-disabled",name:"가상_자료.pdf",sizeLabel:"1KB",status:"ready"}]
        : state === "long" ? Array.from({length:3},(_,index) => ({id:`demo-long-${index}`,name:`가상_자료_${index + 1}_여러_조직의_장기_인재육성_계획과_첨부자료를_포함한_긴_파일명.pdf`,sizeLabel:"1KB",status:"ready"})) : []);
    const addFiles = (selected: File[]) => setFiles(current => [...current,...selected.map(file => ({id:`picked-${nextId.current++}`,name:file.name,
        sizeLabel:file.size < 1024 * 1024 ? `${Math.max(1,Math.round(file.size / 1024))}KB` : `${(file.size / 1024 / 1024).toFixed(1)}MB`,status:"uploading" as const}))]);
    const remove = (id:string) => setFiles(current => current.filter(file => file.id !== id));
    const help = state === "long" ? "설명과 근거는 호출자가 제공합니다. ".repeat(20)+"\n긴 문자열: "+"abcdefghijklmnop".repeat(20) : "가상 후보자 정보 보기";
    return <div className="prism-demo-stack"><PrismSwitch label="알림 사용" checked={checked} onCheckedChange={setChecked} disabled={state === "disabled"} />
        <div className="prism-demo-row">{tooltipPlacements.map(({label,...props})=><PrismTooltip key={label} {...props} content={help}><PrismButton variant="line" disabled={state==="disabled"}>{label}</PrismButton></PrismTooltip>)}
            <PrismTooltip small content="복사"><PrismButton variant="line" disabled={state==="disabled"}>소형 도움말</PrismButton></PrismTooltip></div>
        <PrismSummaryBadge label="가상" summary="데모 데이터의 설명을 표시합니다." note={help}/>
        <PrismProgress value={state === "loading" ? null : 65} showPercent />
        <PrismFileDropzone files={files} onFilesSelected={addFiles} onRemove={remove} disabled={state === "disabled"}
            onInvalid={reason => setFeedback(reason === "partial" ? "일부 파일만 첨부되었습니다." : reason === "extension" ? "허용되지 않는 파일 형식입니다." : reason === "size" ? "파일 크기가 제한을 초과했습니다." : "파일 개수가 제한을 초과했습니다.")} />
        <PrismFileAttach files={files} onFilesSelected={addFiles} onRemove={remove} disabled={state === "disabled"} />
        <p className="prism-help">선택한 파일은 서버에 전송하지 않습니다. 업로드 중 상태는 아래 버튼으로 완료할 수 있습니다.</p>
        <PrismButton variant="line" disabled={state === "disabled" || !files.some(file => file.status === "uploading")}
            onClick={() => setFiles(current => current.map(file => file.status === "uploading" ? {...file,status:"ready"} : file))}>가상 업로드 완료</PrismButton>
        {feedback && <PrismToast title={feedback} tone="error" onClose={() => setFeedback("")} />}</div>;
}

